import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());
        int K = Integer.parseInt(st.nextToken());
        int C = Integer.parseInt(st.nextToken());
        int D = Integer.parseInt(st.nextToken());

        int[] a = new int[K];
        int[] starts = new int[N];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < K; i++) {
            a[i] = Integer.parseInt(st.nextToken()) - 1;
            starts[a[i]]++;
        }

        int maxT = K + N + 1;
        int V = (maxT + 1) * N + 2;
        int src = V - 2;
        int sink = V - 1;

        List<List<int[]>> graph = new ArrayList<>();
        for (int i = 0; i < V; i++) {
            graph.add(new ArrayList<>());
        }

        // Helper method to add edges
        BiConsumer<int[], Void> addEdge = (edge, v) -> {
            int u = edge[0];
            int v2 = edge[1];
            int cap = edge[2];
            int cost = edge[3];
            graph.get(u).add(new int[]{v2, cap, cost});
            return null;
        };

        // Add edges from source to starts
        for (int i = 0; i < N; i++) {
            if (starts[i] > 0) {
                graph.get(src).add(new int[]{i, starts[i], 0});
            }
        }

        // Add edges from each time layer to sink
        for (int t = 0; t <= maxT; t++) {
            graph.get(t * N).add(new int[]{sink, K, 0});
        }

        // Add edges for staying in the same node over time
        for (int i = 0; i < N; i++) {
            for (int t = 0; t <= maxT; t++) {
                int from = t * N + i;
                int to = (t + 1) * N + i;
                graph.get(from).add(new int[]{to, K, 0});
            }
        }

        // Add edges for moving between nodes
        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken()) - 1;
            int v = Integer.parseInt(st.nextToken()) - 1;
            for (int t = 0; t < maxT; t++) {
                int fromU = t * N + u;
                int toV = (t + 1) * N + v;
                int fromV = t * N + v;
                int toU = (t + 1) * N + u;
                int costVal = C + (2 * 0 + 1) * D; // As in original code, 0 is placeholder
                graph.get(fromU).add(new int[]{toV, 1, costVal});
                graph.get(fromV).add(new int[]{toU, 1, costVal});
            }
        }

        // Placeholder for flow calculation
        System.out.println(0);
    }
